import datetime
import streamlit as st

# Set up title
st.title("Age Verification Form")

# Calculate date 18 years ago from today
today = datetime.date.today()
eighteen_years_ago = today - datetime.timedelta(days=18 * 365.25)

# Date input widget (defaulting to 18 years ago)
dob = st.date_input(
    "Select your Date of Birth:",
    value=eighteen_years_ago,
    max_value=today,
    min_value=datetime.date(1900, 1, 1),
)
 #Submit button
if st.button("Submit"):
    # Calculate exact age
    age = (
        today.year
        - dob.year
        - ((today.month, today.day) < (dob.month, dob.day))
    )

    # Logic check
    if age >= 18:
        st.success("Submitted successfully!")
    else:
        st.error("You are not eligible.")


   
